<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #f4f5f7;
    color: #172b4d;
    padding: 24px;
  }
  h1 {
    margin: 0 0 16px;
    font-size: 22px;
  }
  .toolbar {
    display: flex;
    gap: 8px;
    margin-bottom: 20px;
  }
  #new-card {
    flex: 1;
    max-width: 320px;
    padding: 10px 12px;
    border: 1px solid #dfe1e6;
    border-radius: 6px;
    font-size: 14px;
  }
  #add-card {
    padding: 10px 16px;
    border: none;
    border-radius: 6px;
    background: #0052cc;
    color: #fff;
    font-size: 14px;
    cursor: pointer;
  }
  #add-card:hover { background: #0747a6; }

  .board {
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }
  .column {
    background: #ebecf0;
    border-radius: 8px;
    width: 300px;
    min-height: 200px;
    padding: 10px;
    display: flex;
    flex-direction: column;
    transition: background 0.15s;
  }
  .column.drag-over {
    background: #d6dae0;
  }
  .column-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 8px 10px;
    font-weight: 600;
    font-size: 14px;
  }
  .count {
    background: #dfe1e6;
    border-radius: 12px;
    padding: 2px 9px;
    font-size: 12px;
    font-weight: 600;
    color: #42526e;
  }
  .card-container {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-height: 60px;
    flex: 1;
  }
  .card {
    background: #fff;
    border-radius: 6px;
    padding: 10px 10px 10px 12px;
    box-shadow: 0 1px 2px rgba(9,30,66,0.25);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    cursor: grab;
    font-size: 14px;
    line-height: 1.4;
  }
  .card:active { cursor: grabbing; }
  .card.dragging { opacity: 0.4; }
  .card-title {
    word-break: break-word;
    flex: 1;
  }
  .card-del {
    border: none;
    background: transparent;
    color: #97a0af;
    font-size: 16px;
    line-height: 1;
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 4px;
    flex-shrink: 0;
  }
  .card-del:hover {
    background: #ffebe6;
    color: #de350b;
  }
</style>
</head>
<body>

<h1>Kanban Board</h1>

<div class="toolbar">
  <input type="text" id="new-card" placeholder="New card title...">
  <button id="add-card">Add Card</button>
</div>

<div class="board">
  <div class="column" id="col-todo" data-status="todo">
    <div class="column-header">
      <span>To Do</span>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-doing" data-status="doing">
    <div class="column-header">
      <span>Doing</span>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-done" data-status="done">
    <div class="column-header">
      <span>Done</span>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>
</div>

<script>
(function () {
  const STORAGE_KEY = 'kanban-board-state';
  const columns = {
    todo: document.getElementById('col-todo'),
    doing: document.getElementById('col-doing'),
    done: document.getElementById('col-done')
  };

  let idCounter = 1;

  function loadState() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || !Array.isArray(parsed.cards)) return null;
      return parsed;
    } catch (e) {
      return null;
    }
  }

  function saveState() {
    const cards = [];
    Object.keys(columns).forEach(status => {
      const container = columns[status].querySelector('.card-container');
      container.querySelectorAll('.card').forEach(cardEl => {
        cards.push({
          id: cardEl.dataset.id,
          title: cardEl.dataset.title,
          status: status
        });
      });
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ cards: cards }));
  }

  function updateCounts() {
    Object.keys(columns).forEach(status => {
      const col = columns[status];
      const container = col.querySelector('.card-container');
      const count = container.querySelectorAll('.card').length;
      col.querySelector('.count').textContent = count;
    });
  }

  function createCardElement(id, title) {
    const card = document.createElement('div');
    card.className = 'card';
    card.draggable = true;
    card.dataset.id = id;
    card.dataset.title = title;

    const titleSpan = document.createElement('span');
    titleSpan.className = 'card-title';
    titleSpan.textContent = title;

    const delBtn = document.createElement('button');
    delBtn.className = 'card-del';
    delBtn.textContent = '\u2715';
    delBtn.setAttribute('aria-label', 'Delete card');
    delBtn.addEventListener('click', function () {
      card.remove();
      updateCounts();
      saveState();
    });

    card.appendChild(titleSpan);
    card.appendChild(delBtn);

    card.addEventListener('dragstart', function (e) {
      card.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', card.dataset.id);
    });

    card.addEventListener('dragend', function () {
      card.classList.remove('dragging');
    });

    return card;
  }

  function addCard(title, status) {
    const id = 'card-' + (idCounter++) + '-' + status;
    const card = createCardElement(id, title);
    columns[status].querySelector('.card-container').appendChild(card);
    updateCounts();
  }

  Object.keys(columns).forEach(status => {
    const col = columns[status];
    col.addEventListener('dragover', function (e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      col.classList.add('drag-over');
    });

    col.addEventListener('dragleave', function () {
      col.classList.remove('drag-over');
    });

    col.addEventListener('drop', function (e) {
      e.preventDefault();
      col.classList.remove('drag-over');
      const id = e.dataTransfer.getData('text/plain');
      const dragged = document.querySelector('.card[data-id="' + CSS.escape(id) + '"]');
      if (!dragged) return;
      col.querySelector('.card-container').appendChild(dragged);
      updateCounts();
      saveState();
    });
  });

  const input = document.getElementById('new-card');
  const addBtn = document.getElementById('add-card');

  function handleAdd() {
    const text = input.value.trim();
    if (!text) return;
    addCard(text, 'todo');
    input.value = '';
    saveState();
  }

  addBtn.addEventListener('click', handleAdd);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      handleAdd();
    }
  });

  function init() {
    const state = loadState();
    if (state && state.cards.length) {
      state.cards.forEach(c => {
        const status = columns[c.status] ? c.status : 'todo';
        const card = createCardElement(c.id, c.title);
        columns[status].querySelector('.card-container').appendChild(card);
        const num = parseInt((c.id || '').replace(/[^0-9]/g, ''), 10);
        if (!isNaN(num) && num >= idCounter) idCounter = num + 1;
      });
      updateCounts();
    } else {
      updateCounts();
      saveState();
    }
  }

  init();
})();
</script>

</body>
</html>
